      intro: 'Анимированный GIF — это стопка кадров с индексированными цветами, не более 256 цветов на палитру, без межкадрового сжатия, кроме простого кодирования длин серий. Поэтому GIF на несколько секунд может весить больше, чем MP4 на минуту, и поэтому сделать хороший GIF — это в основном выбрать ширину, частоту кадров и размер палитры. Эта страница запускает двухэтапный конвейер: FFmpeg масштабирует видео до заданной вами ширины и выбирает кадры с вашей частотой, записывая сырой GIF, затем gifsicle переквантует палитру до вашего числа цветов, задает задержку кадра и оптимизирует кадры так, чтобы сохранялись только измененные пиксели. Значения по умолчанию настроены для записей экрана: ширина 900 пикселей, 12 кадров в секунду, 128 цветов.',
