      intro: 'HTTP Live Streaming отдает видео как плейлист коротких сегментов на нескольких уровнях качества, чтобы плеер быстро стартовал и переключал уровни при изменении соединения. Собрать такой пакет вручную — значит закодировать каждый вариант с выровненными ключевыми кадрами, разрезать их на сегменты и написать мастер-плейлист, который правильно описывает каждый вариант. Эта страница делает всю работу: она проверяет вашу загрузку, предлагает уровни лестницы, которые допускают ваш источник и тариф, кодирует каждый из них с помощью libx264 и AAC в 2-секундные сегменты MPEG-TS, при желании добавляет субтитры от нашего собственного транскрибатора Whisper, спрайт-лист раскадровки и I-frame-плейлист для перемотки и упаковывает все в tar.gz или zip, который можно распаковать на любой статический хостинг.',
