      intro: 'Модели реставрации видео расходятся друг с другом. GAN-апскейлер вроде Real-ESRGAN дает четкие отдельные кадры, которые могут мерцать в движении; видеотрансформер вроде VRT сохраняет последовательность стабильной, но может смягчать детали. Единственный честный способ выбрать — прогнать один и тот же материал через все модели и посмотреть. Эта страница делает именно это на фрагменте до 15 секунд: извлекает кадры, запускает выбранные вами модели из шести на нашем собственном GPU, собирает каждый результат обратно в MP4 с исходной частотой кадров и оригинальным звуком и упаковывает все, включая нетронутый фрагмент, в один архив для сравнения рядом. Каждое число ниже взято из конвейера в том виде, в каком он работает сегодня.',
