      intro: '«ИИ-сканирование документов» превращает одну или несколько сфотографированных или отсканированных страниц в многостраничный PDF с поиском и, по вашему запросу, в редактируемый документ Word. Оно обрабатывает два вида страниц по-разному и сообщает, какая есть какая. Печатные или машинописные страницы проходят через OCRmyPDF и Tesseract: выходная страница — ваш скан, нетронутый, с невидимым текстовым слоем под ним, чтобы вы могли искать, выделять и копировать. Рукописные страницы читает визуально-языковая модель, работающая на нашем собственном GPU, которая транскрибирует написанное слово в слово, помечает нечитаемое как [illegible], оборачивает сомнительное слово в [?: предположение] и получает указание никогда ничего не дописывать, не исправлять и не приглаживать. Одна задача может смешивать оба вида страниц в заданном вами порядке, а результат называет движок и уверенность для каждой страницы.',
