        'Шаблоны PII — регулярные выражения: электронная почта (локальная часть, @, домен с точкой и TLD из 2+ букв); североамериканский номер телефона из 10 цифр с необязательными +1, скобками, точками, пробелами или дефисами; три, две и четыре цифры, разделенные дефисом или пробелом; от 13 до 19 цифр, необязательно разделенных пробелами или дефисами (номера карт); и номер дома, за которым следуют название и слово типа улицы. Шаблонов для личных имен, дат рождения и идентификаторов за пределами США нет.',
