        'Певцам полезнее репетировать под настоящую аранжировку, чем под MIDI-приближение.',
        'Возврат стема в формате входа сохраняет файл размера для телефона таким же; MP3 на 10 МБ не должен случайно превращаться в загрузку на 50 МБ.',
